for p in products:
    SL = shelf_life[p]
    I[p] = m.addVars(locations, periods, range(1, SL+1), vtype=GRB.INTEGER, name=f"I_{p}")

# Sales variables: similar to inventory
sales = {}
for p in products:
    SL = shelf_life[p]
    sales[p] = m.addVars(locations, periods, range(1, SL+1), vtype=GRB.INTEGER, name=f"sales_{p}")

