# 3. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in periods:
            m.addConstr(W[p,l,t] == I[p][l,t,1] - sales[p][l,t,1], name=f"waste_{p}_{l}_{t}")

# 4. Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(1, SL+1):
                m.addConstr(sales[p][l,t,r] <= I[p][l,t,r], name=f"sales_avail_{p}_{l}_{t}_{r}")

# 5. Demand fulfillment: for each d,l,t, sum_{p in substitutes[d]} A[p,d,l,t] + L[d,l,t] = D[d,l,t]
for d in products:
    for l in locations:
        for t in periods:
            demand_val = demand_share[l] * demand_curve[d][t-1]  # t-1 for 0-indexed list
            m.addConstr(gp.quicksum(A[p][d,l,t] for p in substitutes[d]) + L[d,l,t] == demand_val, name=f"demand_fulfill_{d}_{l}_{t}")

# 6. Sales total: for each p,l,t, sum_r sales[p,l,t,r] = sum_{d in product_serves[p]} A[p,d,l,t]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in periods:
            total_sales = gp.quicksum(sales[p][l,t,r] for r in range(1, SL+1))
            total_alloc = gp.quicksum(A[p][d,l,t] for d in product_serves[p])
            m.addConstr(total_sales == total_alloc, name=f"sales_total_{p}_{l}_{t}")

# 7. Production capacity: Q[p,t] <= production_cap[p][t-1]
for p in products:
    for t in periods:
        cap = production_cap[p][t-1]  # t-1 for 0-indexed list
        m.addConstr(Q[p,t] <= cap, name=f"production_cap_{p}_{t}")

# 8. Storage capacity: for each l,t, sum_p ( cold_usage[p] * sum_r I[p,l,t,r] ) <= cold_capacity[l]
for l in locations:
