# Objective function
obj = gp.QuadExpr()

# Purchasing cost: sum_{p,t} costs.purchasing[p] * Q[p,t]
for p in products:
    for t in periods:
        obj += costs['purchasing'][p] * Q[p,t]

# Holding cost: sum_{p,l,t} sum_{r=2}^{SL} costs.inventory[p] * (I[p,l,t,r] - sales[p,l,t,r])
for p in products:
    SL = shelf_life[p]
