# Waste cost: sum_{p,l,t} costs.waste[p] * W[p,l,t]
for p in products:
    for l in locations:
        for t in periods:
            obj += costs['waste'][p] * W[p,l,t]

# Lost sales cost: sum_{d,l,t} costs.lost_sales[d] * L[d,l,t]
for d in products:
    for l in locations:
        for t in periods:
            obj += costs['lost_sales'][d] * L[d,l,t]

m.setObjective(obj, GRB.MINIMIZE)

# Solve
m.optimize()

# Print results
print(f"status: {m.Status}")
if m.Status == GRB.OPTIMAL:
