LS = {}  # Lost sales for product j at location l in period t
for j in P:
    for l in L:
        for t in T_range:
            LS[j, l, t] = m.addVar(vtype=GRB.CONTINUOUS, name=f"LS_{j}_{l}_{t}")

# Constraints

# Fresh inflow constraint: for each p, l, t, I at r=SL[p] is set by production
for p in P:
    sl_p = SL[p]
    for l in L:
        for t in T_range:
