import gurobipy as gp
from gurobipy import GRB
import json

# Create model
m = gp.Model()

# Set parameters
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Extract data from pre-defined 'data' variable
products = data["products"]
locations = data["locations"]
periods = list(range(data["periods"]))  # 0 to 19
shelf_life = data["shelf_life"]
demand = data["demand"]
demand_share = data["demand_share"]
production_cap = data["production_capacity"]
cold_capacity = data["cold_storage_capacity"]
cold_usage = data["cold_storage_usage"]
cost_purchasing = data["cost_purchasing"]
cost_inventory_holding = data["cost_inventory_holding"]
cost_waste = data["cost_waste"]
cost_lost_sales = data["cost_lost_sales"]
sub_edges = data["network"]["sub_edges"]

# Create substitution groups
graph = {}
for p in products:
    graph[p] = set()
for edge in sub_edges:
    a, b = edge
    graph[a].add(b)
    graph[b].add(a)

visited = set()
groups = []
for p in products:
    if p not in visited:
        group_set = set()
        stack = [p]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                group_set.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        stack.append(neighbor)
        groups.append(group_set)

# Map each product to its group
product_group = {}
for group in groups:
    for p in group:
        product_group[p] = group

# Define decision variables
Q = m.addVars(products, periods, name="Q")  # Production quantity
I = {}  # Inventory: I[p,l,t,r]
sales = {}  # Sales: sales[p,l,t,r]
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(1, sl + 1):
                I[p, l, t, r] = m.addVar(name=f"I_{p}_{l}_{t}_{r}")
                sales[p, l, t, r] = m.addVar(name=f"sales_{p}_{l}_{t}_{r}")

W = m.addVars(products, locations, periods, name="W")  # Waste
lost_sales = m.addVars(products, locations, periods, name="lost_sales")  # Lost sales

# sub_sales variables: for each p, q in product_group[p], l, t
sub_sales = {}
for p in products:
    group_p = product_group[p]
    for q in group_p:
        for l in locations:
            for t in periods:
                sub_sales[p, q, l, t] = m.addVar(name=f"sub_sales_{p}_{q}_{l}_{t}")

# Constraints

# Production capacity
for p in products:
    for t in periods:
        m.addConstr(Q[p, t] <= production_cap[p][t])

# Initial inventory: for t=0, I[p,l,0,r] = 0 for r < SL, and for r=SL, set by inflow
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for r in range(1, sl):  # r=1 to SL-1
            m.addConstr(I[p, l, 0, r] == 0)
        # For r=SL, set by fresh inflow
        m.addConstr(I[p, l, 0, sl] == Q[p, 0] * demand_share[l])

# Aging and fresh inflow for t>=1
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods:
            if t > 0:  # For t>=1, set fresh inflow
                m.addConstr(I[p, l, t, sl] == Q[p, t] * demand_share[l])
            if t < len(periods) - 1:  # Aging for t from 0 to 18
                for r in range(1, sl):  # r=1 to SL-1
                    m.addConstr(I[p, l, t+1, r] == I[p, l, t, r+1] - sales[p, l, t, r+1])

# Sales availability
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(1, sl + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r])

# Waste
for p in products:
    for l in locations:
        for t in periods:
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1])

# Substitution constraints
# For each p,l,t, total sales of p equals sum of sub_sales for q in group[p]
for p in products:
    group_p = product_group[p]
    for l in locations:
        for t in periods:
            total_sales = gp.quicksum(sales[p, l, t, r] for r in range(1, shelf_life[p] + 1))
            sub_sales_sum = gp.quicksum(sub_sales[p, q, l, t] for q in group_p)
            m.addConstr(total_sales == sub_sales_sum)

# For each q,l,t, demand satisfaction
for q in products:
    group_q = product_group[q]
    for l in locations:
        for t in periods:
            d_qlt = demand[q][t] * demand_share[l]
            sub_sales_sum = gp.quicksum(sub_sales[p, q, l, t] for p in group_q)
            m.addConstr(sub_sales_sum + lost_sales[q, l, t] == d_qlt)

# Storage capacity
for l in locations:
    for t in periods:
        total_cold_usage = gp.quicksum(
            cold_usage[p] * gp.quicksum(I[p, l, t, r] for r in range(1, shelf_life[p] + 1))
            for p in products
        )
        m.addConstr(total_cold_usage <= cold_capacity[l])

# Objective function
purchasing_cost = gp.quicksum(
    cost_purchasing[p] * Q[p, t] for p in products for t in periods
)

holding_cost = gp.quicksum(
    cost_inventory_holding[p] * (I[p, l, t, r] - sales[p, l, t, r])
    for p in products
    for l in locations
    for t in periods
    for r in range(2, shelf_life[p] + 1)  # r>=2
)

waste_cost = gp.quicksum(
    cost_waste[p] * W[p, l, t] for p in products for l in locations for t in periods
)

lost_sales_cost = gp.quicksum(
    cost_lost_sales[p] * lost_sales[p, l, t] for p in products for l in locations for t in periods
)

total_cost = purchasing_cost + holding_cost + waste_cost + lost_sales_cost
m.setObjective(total_cost, GRB.MINIMIZE)

# Optimize
m.optimize()

# Print results
print(f"status: {m.Status}")
if m.Status == GRB.OPTIMAL:
    print(f"objective: {m.ObjVal}")
