# Create model
m = gp.Model()

# Sets
periods_list = list(range(1, data['num_periods'] + 1))
products = data['products']
locations = data['locations']
shelf_life = data['shelf_life']

# Allowed substitution pairs from network
sub_edges = data['network']['sub_edges']
allowed_pairs = []
for p in products:
    allowed_pairs.append((p, p))
for edge in sub_edges:
    allowed_pairs.append((edge[0], edge[1]))

# Decision variables
Q = {}  # Production quantity
for p in products:
    for t in periods_list:
        Q[p, t] = m.addVar(lb=0, ub=data['production_capacity'][p][t-1], name=f"Q_{p}_{t}")

I = {}  # Inventory at start of period t with remaining life r
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods_list:
            for r in range(1, sl + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}  # Sales from inventory with remaining life r
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods_list:
            for r in range(1, sl + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

W = {}  # Waste
for p in products:
    for l in locations:
        for t in periods_list:
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

sales_alloc = {}  # Sales allocation for substitution
for (p_prime, p) in allowed_pairs:
    for l in locations:
        for t in periods_list:
            sales_alloc[p_prime, p, l, t] = m.addVar(lb=0, name=f"sales_alloc_{p_prime}_{p}_{l}_{t}")

lost_sales = {}  # Lost sales
for p in products:
    for l in locations:
        for t in periods_list:
            lost_sales[p, l, t] = m.addVar(lb=0, name=f"lost_sales_{p}_{l}_{t}")

# Constraints

# Initial inventory: zero at t=1 for all p, l, r
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for r in range(1, sl + 1):
            m.addConstr(I[p, l, 1, r] == 0, name=f"init_inv_{p}_{l}_{r}")

# Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods_list:
            m.addConstr(I[p, l, t, sl] == Q[p, t] * data['demand_share'][l], name=f"fresh_inflow_{p}_{l}_{t}")

# Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in range(1, data['num_periods']):  # t from 1 to 19
            for r in range(1, sl):  # r from 1 to SL-1
                m.addConstr(I[p, l, t+1, r] == I[p, l, t, r+1] - sales[p, l, t, r+1], name=f"aging_{p}_{l}_{t}_{r}")

# Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in periods_list:
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1], name=f"waste_{p}_{l}_{t}")

# Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods_list:
            for r in range(1, sl + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r], name=f"sales_avail_{p}_{l}_{t}_{r}")

# Substitution constraints
# For each product p', total sales allocation equals total sales
for p_prime in products:
    for l in locations:
        for t in periods_list:
            total_sales = gp.quicksum(sales[p_prime, l, t, r] for r in range(1, shelf_life[p_prime] + 1))
            alloc_sum = gp.quicksum(sales_alloc[p_prime, p, l, t] for p in products if (p_prime, p) in allowed_pairs)
            m.addConstr(alloc_sum == total_sales, name=f"sales_alloc_sum_{p_prime}_{l}_{t}")

# Demand satisfaction and lost sales
for p in products:
    for l in locations:
        for t in periods_list:
            D_plt = data['demand_share'][l] * data['demand'][p][t-1]  # demand for p at l in t
            alloc_for_p = gp.quicksum(sales_alloc[p_prime, p, l, t] for p_prime in products if (p_prime, p) in allowed_pairs)
            m.addConstr(alloc_for_p <= D_plt, name=f"demand_upper_{p}_{l}_{t}")
            m.addConstr(lost_sales[p, l, t] == D_plt - alloc_for_p, name=f"lost_sales_{p}_{l}_{t}")

# Storage capacity constraint
for l in locations:
    for t in periods_list:
        total_cold_usage = gp.quicksum(
            data['cold_usage'][p] * gp.quicksum(I[p, l, t, r] for r in range(1, shelf_life[p] + 1))
            for p in products
        )
        m.addConstr(total_cold_usage <= data['cold_capacity'][l], name=f"storage_cap_{l}_{t}")

# Objective function
cost_purchase = gp.quicksum(data['purchasing_cost'][p] * Q[p, t] for p in products for t in periods_list)
cost_holding = gp.quicksum(
    data['inventory_holding_cost'][p] * (I[p, l, t, r] - sales[p, l, t, r])
    for p in products for l in locations for t in periods_list for r in range(2, shelf_life[p] + 1)
)
cost_waste = gp.quicksum(data['waste_cost'][p] * W[p, l, t] for p in products for l in locations for t in periods_list)
cost_lost_sales = gp.quicksum(data['lost_sales_cost'][p] * lost_sales[p, l, t] for p in products for l in locations for t in periods_list)

total_cost = cost_purchase + cost_holding + cost_waste + cost_lost_sales
m.setObjective(total_cost, GRB.MINIMIZE)

# Set parameters
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Solve
m.optimize()

# Output
print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
