for p in products:
    cost_waste = data['costs']['waste'][p]
    for l in locations:
        for t in periods:
            cost += cost_waste * W[p, l, t]

for p in products:
    cost_lost = data['costs']['lost_sales'][p]
    for l in locations:
        for t in periods:
            cost += cost_lost * lost_sales[p, l, t]

m.setObjective(cost, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == GRB.OPTIMAL:
