purchasing_cost = gp.quicksum(data['costs']['purchasing'][p] * Q[p,t] for p in products for t in periods_list)
holding_cost = gp.quicksum(data['costs']['inventory'][p] * (I[p,l,t,r] - sales[p,l,t,r]) for p in products for l in locations for t in periods_list for r in range(2, shelf_life[p]+1))
