import gurobipy as gp
from gurobipy import GRB
import json

# Model setup
m = gp.Model()
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Data is pre-defined as 'data'
products = data['products']
locations = data['locations']
periods = list(range(1, data['periods'] + 1))
shelf_life = data['shelf_life']
lead_time = data['lead_time']
cold_capacity = data['cold_capacity']
cold_usage = data['cold_usage']
production_cap = data['production_cap']
demand_curve = data['demand_curve']
demand_share = data['demand_share']
costs = data['costs']
c_pur = costs['purchasing']
c_inv = costs['inventory']
c_waste = costs['waste']
c_lost = costs['lost_sales']
sub_edges = data['network']['sub_edges']

# Define supply_set for each product
supply_set = {p: {p} for p in products}
for edge in sub_edges:
    p1, p2 = edge
    supply_set[p1].add(p2)
    supply_set[p2].add(p1)

# Decision variables
O = m.addVars(products, periods, vtype=GRB.INTEGER, name="O")
Q = m.addVars(products, periods, vtype=GRB.INTEGER, name="Q")
I_indices = []
for p in products:
    for l in locations:
        for t in periods:
            for r in range(1, shelf_life[p] + 1):
                I_indices.append((p, l, t, r))
I = m.addVars(I_indices, vtype=GRB.INTEGER, name="I")
sales_indices = []
for p in products:
    for l in locations:
        for t in periods:
            for r in range(1, shelf_life[p] + 1):
                sales_indices.append((p, l, t, r))
sales = m.addVars(sales_indices, vtype=GRB.INTEGER, name="sales")
lost_sales = m.addVars(products, locations, periods, vtype=GRB.INTEGER, name="lost_sales")
sales_flow_indices = []
for q in products:
    for p in supply_set[q]:
        for l in locations:
            for t in periods:
                sales_flow_indices.append((q, p, l, t))
sales_flow = m.addVars(sales_flow_indices, vtype=GRB.INTEGER, name="sales_flow")
W = m.addVars(products, locations, periods, vtype=GRB.INTEGER, name="W")

# Constraints for Q from O and lead time
for p in products:
    for t in periods:
        if t <= lead_time[p]:
            m.addConstr(Q[p, t] == 0)
        else:
            m.addConstr(Q[p, t] == O[p, t - lead_time[p]])

# Production capacity constraints
for p in products:
    for t in periods:
        m.addConstr(O[p, t] <= production_cap[p][t - 1])

# Initial inventory constraints
for p in products:
    for l in locations:
        for r in range(1, shelf_life[p] + 1):
            m.addConstr(I[p, l, 1, r] == 0)

# Fresh inflow constraints
for p in products:
    for l in locations:
        for t in periods:
            sl = shelf_life[p]
            m.addConstr(I[p, l, t, sl] == Q[p, t] * demand_share[l])

# Aging constraints
for p in products:
    for l in locations:
        for t in periods:
            if t < max(periods):  # t from 1 to 19
                for r in range(1, shelf_life[p]):  # r from 1 to SL-1
                    m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1])

# Waste constraints
for p in products:
    for l in locations:
        for t in periods:
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1])

# Sales availability constraints
for p in products:
    for l in locations:
        for t in periods:
            for r in range(1, shelf_life[p] + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r])
                m.addConstr(sales[p, l, t, r] >= 0)

# Demand satisfaction with substitution
for p in products:
    for l in locations:
        for t in periods:
            total_sales_for_p = gp.quicksum(sales_flow[q, p, l, t] for q in supply_set[p])
            m.addConstr(total_sales_for_p + lost_sales[p, l, t] == demand_curve[p][t - 1] * demand_share[l])
            m.addConstr(lost_sales[p, l, t] >= 0)

# Total sales consistency for each product
for q in products:
    for l in locations:
        for t in periods:
            total_sales_of_q = gp.quicksum(sales[q, l, t, r] for r in range(1, shelf_life[q] + 1))
            total_flow_from_q = gp.quicksum(sales_flow[q, p, l, t] for p in supply_set[q])
            m.addConstr(total_sales_of_q == total_flow_from_q)

# Storage capacity constraints
for l in locations:
    for t in periods:
        total_cold_usage = gp.quicksum(
            cold_usage[p] * gp.quicksum(I[p, l, t, r] for r in range(1, shelf_life[p] + 1))
            for p in products
        )
        m.addConstr(total_cold_usage <= cold_capacity[l])

# Objective function
purchasing_cost = gp.quicksum(c_pur[p] * O[p, t] for p in products for t in periods)
holding_cost = gp.quicksum(
    c_inv[p] * (I[p, l, t, r] - sales[p, l, t, r])
    for p in products for l in locations for t in periods for r in range(2, shelf_life[p] + 1)
)
waste_cost = gp.quicksum(c_waste[p] * W[p, l, t] for p in products for l in locations for t in periods)
lost_sales_cost = gp.quicksum(c_lost[p] * lost_sales[p, l, t] for p in products for l in locations for t in periods)
total_cost = purchasing_cost + holding_cost + waste_cost + lost_sales_cost
m.setObjective(total_cost, GRB.MINIMIZE)

# Optimize
m.optimize()

# Output
print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
