production_cap = data["production_cap"]
costs = data["costs"]

# Create lists for indices with shelf life
I_indices = []
sales_indices = []
T_ship_indices = []
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(1, sl + 1):
                I_indices.append((p, l, t, r))
                sales_indices.append((p, l, t, r))
    for l in spokes:
        for t in periods:
            for r in range(1, sl + 1):
                T_ship_indices.append((p, l, t, r))

# Decision variables
Q = m.addVars(products, periods, name="Q", lb=0)
I = m.addVars(I_indices, name="I", lb=0)
sales = m.addVars(sales_indices, name="sales", lb=0)
T_ship = m.addVars(T_ship_indices, name="T_ship", lb=0)
L = m.addVars(products, locations, periods, name="L", lb=0)  # lost sales

# Define I_adjusted as a dictionary of expressions
I_adjusted = {}
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(1, sl + 1):
                if l == "DC1":
                    # For hub, subtract outflow to all spokes
                    outflow = gp.quicksum(T_ship[p, l_s, t, r] for l_s in spokes)
                    I_adjusted[p, l, t, r] = I[p, l, t, r] - outflow
                else:
                    # For spokes, add inflow from hub
                    I_adjusted[p, l, t, r] = I[p, l, t, r] + T_ship[p, l, t, r]

# Constraints

# Production capacity
for p in products:
    for t in periods:
        cap = production_cap[p][t - 1]  # 0-indexed access
        m.addConstr(Q[p, t] <= cap, name=f"prod_cap_{p}_{t}")

# Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods:
            m.addConstr(I[p, l, t, sl] == Q[p, t] * demand_share[l], name=f"fresh_inflow_{p}_{l}_{t}")

# Initial inventory for t=1, r < SL: I[p,l,1,r] = 0
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for r in range(1, sl):  # r from 1 to SL-1
            m.addConstr(I[p, l, 1, r] == 0, name=f"init_inv_{p}_{l}_{r}")

# Aging constraint for t>1: I[p,l,t,r] = I_adjusted[p,l,t-1,r+1] - sales[p,l,t-1,r+1] for r=1..SL-1
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods:
            if t > 1:
                for r in range(1, sl):  # r from 1 to SL-1
                    m.addConstr(I[p, l, t, r] == I_adjusted[p, l, t-1, r+1] - sales[p, l, t-1, r+1], name=f"aging_{p}_{l}_{t}_{r}")

# Transshipment inventory constraint: for hub, sum of T_ship over spokes <= I for each p,t,r
for p in products:
    sl = shelf_life[p]
    for t in periods:
        for r in range(1, sl + 1):
            total_shipment = gp.quicksum(T_ship[p, l, t, r] for l in spokes)
            m.addConstr(total_shipment <= I[p, "DC1", t, r], name=f"trans_inv_{p}_{t}_{r}")

# Sales constraint: sales[p,l,t,r] <= I_adjusted[p,l,t,r]
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(1, sl + 1):
                m.addConstr(sales[p, l, t, r] <= I_adjusted[p, l, t, r], name=f"sales_bound_{p}_{l}_{t}_{r}")

# Demand constraint: sum_r sales[p,l,t,r] <= d[p,l,t] and lost sales
for p in products:
    for l in locations:
        for t in periods:
            d_plt = demand_curve[p][t - 1] * demand_share[l]  # demand for p,l,t
            total_sales = gp.quicksum(sales[p, l, t, r] for r in range(1, shelf_life[p] + 1))
            m.addConstr(total_sales <= d_plt, name=f"demand_{p}_{l}_{t}")
            m.addConstr(L[p, l, t] >= d_plt - total_sales, name=f"lost_sales_{p}_{l}_{t}")

# Cold storage capacity: sum_p cold_usage[p] * sum_r I_adjusted[p,l,t,r] <= cold_capacity[l]
for l in locations:
    for t in periods:
        total_cold_usage = gp.quicksum(cold_usage[p] * gp.quicksum(I_adjusted[p, l, t, r] for r in range(1, shelf_life[p] + 1)) for p in products)
        m.addConstr(total_cold_usage <= cold_capacity[l], name=f"cold_cap_{l}_{t}")

# Objective function
purchasing_cost = gp.quicksum(costs["purchasing"][p] * Q[p, t] for p in products for t in periods)
holding_cost = gp.quicksum(costs["inventory"][p] * (I_adjusted[p, l, t, r] - sales[p, l, t, r]) for p in products for l in locations for t in periods for r in range(2, shelf_life[p] + 1))
waste_cost = gp.quicksum(costs["waste"][p] * (I_adjusted[p, l, t, 1] - sales[p, l, t, 1]) for p in products for l in locations for t in periods)
lost_sales_cost = gp.quicksum(costs["lost_sales"][p] * L[p, l, t] for p in products for l in locations for t in periods)
transshipment_cost = gp.quicksum(costs["transshipment"] * T_ship[p, l, t, r] for p in products for l in spokes for t in periods for r in range(1, shelf_life[p] + 1))

total_cost = purchasing_cost + holding_cost + waste_cost + lost_sales_cost + transshipment_cost
m.setObjective(total_cost, GRB.MINIMIZE)

# Optimize
m.optimize()

# Print results
print(f"status: {m.Status}")
if m.Status == GRB.OPTIMAL:
    print(f"objective: {m.ObjVal}")
