holding_cost = gp.quicksum(data['costs']['inventory'][p] * (I[p, l, t, r] + gp.quicksum(T[p, i, l, t, r] for i in locations if i != l) - gp.quicksum(T[p, l, j, t, r] for j in locations if j != l) - sales[p, l, t, r]) for p in products for l in locations for t in periods for r in ranges_r[p] if r >= 2)

