                        # I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1]
                        m.addConstr(I[p, l, t+1, r] == I[p, l, t, r+1] - sales[p, l, t, r+1])

# Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in periods:
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1])

# Sales availability: sales[p,l,t,r] <= I[p,l,t,r] for each p,l,t,r
for p in products:
    for l in locations:
        for t in periods:
            for r in range(1, shelf_life[p] + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r])

# Demand satisfaction: sum_r sales[p,l,t,r] + lost_sales[p,l,t] = demand[p][t] * demand_share[l]
for p in products:
    for l in locations:
        for t in periods:
            demand_val = data['demand'][p][t-1] * data['demand_share'][l]  # t-1 for list index
            total_sales = gp.quicksum(sales[p, l, t, r] for r in range(1, shelf_life[p] + 1))
            m.addConstr(total_sales + lost_sales[p, l, t] == demand_val)

# Storage capacity: sum_p cold_usage[p] * (sum_r I[p,l,t,r]) <= cold_capacity[l] for each l,t
for l in locations:
    for t in periods:
        total_cold_usage = gp.quicksum(data['cold_usage'][p] * gp.quicksum(I[p, l, t, r] for r in range(1, shelf_life[p] + 1)) for p in products)
        m.addConstr(total_cold_usage <= data['cold_capacity'][l])

# Production capacity: Q[p,t] <= production_capacity[p][t-1] for each p,t
for p in products:
    for t in periods:
        m.addConstr(Q[p, t] <= data['production_capacity'][p][t-1])  # t-1 for list index

# Objective function
cost = gp.quicksum(data['purchasing_cost'][p] * Q[p, t] for p in products for t in periods)
# Holding cost for r >= 2
for p in products:
    for l in locations:
        for t in periods:
            for r in range(2, shelf_life[p] + 1):
                cost += data['inventory_holding_cost'][p] * (I[p, l, t, r] - sales[p, l, t, r])
cost += gp.quicksum(data['waste_cost'][p] * W[p, l, t] for p in products for l in locations for t in periods)
cost += gp.quicksum(data['lost_sales_cost'][p] * lost_sales[p, l, t] for p in products for l in locations for t in periods)

m.setObjective(cost, GRB.MINIMIZE)

# Solve
m.optimize()

# Output
print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
